import { useRef, useMemo } from "react";
import usePdfExport from "@/hooks/usePdfExport";
import useCsvExport from "@/hooks/useCsvExport";

// ⛔️ On n'utilise pas ExportButtons tant que l'erreur 310 n'est pas réglée
// import ExportButtons from "@/components/admin/ExportButtons";

import { Card, CardContent } from "@/components/ui/card";
import { Loader2, Briefcase, Users, FileText } from "lucide-react";

import {
  BarChart as RBarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
  CartesianGrid,
} from "recharts";

// Petite util pour valider les “element types”
const isValidElementType = (x) => typeof x === "function" || typeof x === "string";

const StatResumePage = ({ embedMode = false, yearDefault, onYearChange, month, data }) => {
  const exportRef = useRef();
  const year = yearDefault || new Date().getFullYear();

  // 1) Garde-fou data
  const dataOk = data && typeof data === "object" && !Array.isArray(data);
  if (!dataOk) {
    return (
      <div className="bg-white dark:bg-gray-900 p-4 rounded-xl shadow border">
        <div className="flex justify-center items-center h-32">
          <Loader2 className="animate-spin w-6 h-6 text-gray-500" />
          <span className="ml-2">Chargement…</span>
        </div>
      </div>
    );
  }

  // 2) Garde-fou imports (évite l’invariant #310 et donne l’indice)
  const invalids = [];
  if (!isValidElementType(Card)) invalids.push("Card");
  if (!isValidElementType(CardContent)) invalids.push("CardContent");
  if (!isValidElementType(RBarChart)) invalids.push("BarChart (de recharts)");
  if (!isValidElementType(Bar)) invalids.push("Bar (de recharts)");
  if (!isValidElementType(XAxis)) invalids.push("XAxis (de recharts)");
  if (!isValidElementType(YAxis)) invalids.push("YAxis (de recharts)");
  if (!isValidElementType(Tooltip)) invalids.push("Tooltip (de recharts)");
  if (!isValidElementType(ResponsiveContainer)) invalids.push("ResponsiveContainer (de recharts)");
  if (!isValidElementType(CartesianGrid)) invalids.push("CartesianGrid (de recharts)");

  if (invalids.length) {
    return (
      <div className="bg-white dark:bg-gray-900 p-4 rounded-xl shadow border text-sm">
        <p className="font-semibold text-red-600 mb-2">Import invalide → impossible d’afficher le graphique.</p>
        <p>Composants en cause :</p>
        <ul className="list-disc ml-6 mt-2">
          {invalids.map((n) => (
            <li key={n} className="text-red-500">{n}</li>
          ))}
        </ul>
        <p className="mt-3 text-gray-600">
          Vérifie les <em>exports</em>/<em>imports</em> :
          <br/>• Recharts se fait ainsi — <code>import {'{ BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid }'} from "recharts";</code>
          <br/>• Ton UI card doit vraiment exporter <code>Card</code> et <code>CardContent</code> via <code>export {'{ Card, CardContent }'}</code>.
        </p>
      </div>
    );
  }

  // Séries issues de /admin/stats/resume
  const candidaturesParMois     = Array.isArray(data.candidatures_par_mois) ? data.candidatures_par_mois : [];
  const candidaturesParOffre    = Array.isArray(data.candidatures_par_offre) ? data.candidatures_par_offre : [];
  const parTypeContrat          = Array.isArray(data.par_type_contrat) ? data.par_type_contrat : [];
  const parLieu                 = Array.isArray(data.par_lieu) ? data.par_lieu : [];
  const parEmployeur            = Array.isArray(data.par_employeur) ? data.par_employeur : [];
  const multiYearData           = Array.isArray(data.multi_year_data) ? data.multi_year_data : [];
  const actualitesParCategorie  = Array.isArray(data.actualites_par_categorie) ? data.actualites_par_categorie : [];
  const actualitesScope         = typeof data.actualites_scope === "string" ? data.actualites_scope : "year";
  const actualitesYear          = data.actualites_year ?? String(year);

  // Exports
  const header = `Année : ${year}${month ? ` - Mois : ${month}` : ""}`;
  const { exportPDF } = usePdfExport(exportRef, {
    title: "CDOTCHAD - Rapport de Statistiques",
    header,
    filePrefix: `rapport-stats-${year}${month ? `-${month}` : ""}`,
  });
  const { exportCSV } = useCsvExport();

  const csvRows = useMemo(() => {
    const rows = [];
    rows.push(["Statistiques globales"]);
    rows.push(["Candidatures", data.total_candidatures ?? 0]);
    rows.push(["Utilisateurs",  data.total_utilisateurs ?? 0]);
    rows.push(["Offres",        data.total_offres ?? 0]);
    rows.push(["Actualités",    data.total_actualites ?? 0]);
    rows.push([]);
    rows.push(["Candidatures par mois"]); rows.push(["Mois","Total"]);
    candidaturesParMois.forEach((it) => rows.push([it.mois, it.total])); rows.push([]);
    rows.push(["Candidatures par offre"]); rows.push(["Offre","Total"]);
    candidaturesParOffre.forEach((it) => rows.push([it.titre, it.total])); rows.push([]);
    rows.push(["Répartition par type de contrat"]); rows.push(["Type de contrat","Total"]);
    parTypeContrat.forEach((it) => rows.push([it.type_contrat, it.total])); rows.push([]);
    rows.push(["Top 5 régions avec le plus d’offres"]); rows.push(["Lieu","Total"]);
    parLieu.forEach((it) => rows.push([it.lieu, it.total])); rows.push([]);
    rows.push(["Répartition par employeur"]); rows.push(["Employeur","Total"]);
    parEmployeur.forEach((it) => rows.push([it.employeur, it.total])); rows.push([]);
    rows.push([`Actualités par catégorie (scope=${actualitesScope}${actualitesScope==="year" ? `, year=${actualitesYear}` : ""})`]);
    rows.push(["Catégorie","Total"]);
    actualitesParCategorie.forEach((it) => rows.push([it.categorie, it.total])); rows.push([]);
    rows.push(["Évolution mensuelle multi-année"]); rows.push(["Mois", `${year}`, `${Number(year)+1}`]);
    for (let i=1; i<=12; i++){
      const m = String(i).padStart(2,"0");
      const v1 = multiYearData.find(d => d.annee === String(year) && d.mois === m)?.total || 0;
      const v2 = multiYearData.find(d => d.annee === String(Number(year)+1) && d.mois === m)?.total || 0;
      rows.push([m, v1, v2]);
    }
    return rows;
  }, [data, year, month, candidaturesParMois, candidaturesParOffre, parTypeContrat, parLieu, parEmployeur, actualitesParCategorie, actualitesScope, actualitesYear, multiYearData]);

  return (
    <div className="space-y-6 px-4 py-8">
      <div className="flex flex-wrap gap-3 items-center">
        <select
          value={year}
          onChange={(e) => onYearChange?.(Number(e.target.value))}
          className="border rounded px-2 py-1 text-sm"
        >
          {[new Date().getFullYear(), 2024, 2023, 2022].map((y) => (
            <option key={y} value={y}>{y}</option>
          ))}
        </select>

        {month && (
          <span className="text-xs text-gray-500">Mois filtré : <strong>{String(month)}</strong></span>
        )}

        <button
          type="button"
          onClick={exportPDF}
          className="bg-blue-600 text-white px-3 py-1 rounded text-sm"
        >
          Exporter PDF
        </button>
        <button
          type="button"
          onClick={() => exportCSV(csvRows, `stats-resume-${year}${month ? `-${month}` : ""}`)}
          className="bg-green-600 text-white px-3 py-1 rounded text-sm"
        >
          Exporter CSV
        </button>
      </div>

      <div ref={exportRef} className="space-y-10">
        {/* cartes */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <Card className="border-l-4 border-blue-600 shadow-sm">
            <CardContent className="p-6 flex items-center justify-between">
              <div>
                <p className="text-gray-500">Candidatures</p>
                <p className="text-3xl font-bold">{data.total_candidatures ?? 0}</p>
              </div>
              <FileText className="w-8 h-8 text-blue-600" />
            </CardContent>
          </Card>
          <Card className="border-l-4 border-green-600 shadow-sm">
            <CardContent className="p-6 flex items-center justify-between">
              <div>
                <p className="text-gray-500">Utilisateurs</p>
                <p className="text-3xl font-bold">{data.total_utilisateurs ?? 0}</p>
              </div>
              <Users className="w-8 h-8 text-green-600" />
            </CardContent>
          </Card>
          <Card className="border-l-4 border-indigo-600 shadow-sm">
            <CardContent className="p-6 flex items-center justify-between">
              <div>
                <p className="text-gray-500">Offres</p>
                <p className="text-3xl font-bold">{data.total_offres ?? 0}</p>
              </div>
              <Briefcase className="w-8 h-8 text-indigo-600" />
            </CardContent>
          </Card>
          <Card className="border-l-4 border-rose-600 shadow-sm">
            <CardContent className="p-6 flex items-center justify-between">
              <div>
                <p className="text-gray-500">Actualités</p>
                <p className="text-3xl font-bold">{data.total_actualites ?? 0}</p>
              </div>
              <FileText className="w-8 h-8 text-rose-600" />
            </CardContent>
          </Card>
        </div>

        {/* graphiques/tableaux… (inchangé, rendus uniquement si imports valides) */}
        {/* Candidatures par mois */}
        <div className="bg-white rounded-xl p-4 shadow-sm border">
          <h2 className="text-lg font-semibold mb-2">Candidatures par mois — {year}</h2>
          {candidaturesParMois.length ? (
            <ResponsiveContainer width="100%" height={300}>
              <RBarChart data={candidaturesParMois}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="mois" />
                <YAxis allowDecimals={false} />
                <Tooltip />
                <Bar dataKey="total" />
              </RBarChart>
            </ResponsiveContainer>
          ) : <p className="text-gray-500">Aucune donnée disponible.</p>}
        </div>

        {/* … le reste de la page (par offre, type contrat, lieu, employeur, multi-année, actualités) identique à ta version actuelle */}
        {/* Pour tenir court, je n'ai pas recollé les sections suivantes ; garde celles de ta dernière version safe. */}
      </div>
    </div>
  );
};

export default StatResumePage;
