// 📁 src/hooks/usePdfExport.js
import html2canvas from "html2canvas";
import jsPDF from "jspdf";

/**
 * Usage:
 *  const exportRef = useRef();
 *  const { exportPDF } = usePdfExport(exportRef, {
 *    title: "CDOTCHAD - Rapport de Statistiques",
 *    header: "Année : 2025 - Mois : 06",
 *    filePrefix: "rapport-stats-2025-06"
 *  });
 *  // puis <ExportButtons onPdf={exportPDF} ... />
 */
export default function usePdfExport(
  ref,
  { title = "Rapport", header = "", filePrefix = "rapport" } = {}
) {
  const exportPDF = async () => {
    const el = ref?.current;
    if (!el) return;

    const canvas = await html2canvas(el, {
      scale: 2,
      useCORS: true,
      allowTaint: true,
      backgroundColor: "#ffffff",
      logging: false,
    });

    const imgData = canvas.toDataURL("image/png");
    const pdf = new jsPDF("p", "mm", "a4");
    const pdfWidth = pdf.internal.pageSize.getWidth();
    const pdfHeight = pdf.internal.pageSize.getHeight();
    const imgHeight = (canvas.height * pdfWidth) / canvas.width;

    let heightLeft = imgHeight;

    // En-tête
    pdf.setFontSize(12);
    pdf.setTextColor(40);
    pdf.text(title, 14, 10);
    if (header) {
      pdf.setFontSize(10);
      pdf.text(header, 14, 16);
    }

    // Image principale
    pdf.addImage(imgData, "PNG", 0, 20, pdfWidth, imgHeight);
    heightLeft -= (pdfHeight - 20);

    // Pages suivantes si nécessaire
    while (heightLeft > 0) {
      pdf.addPage();
      pdf.addImage(
        imgData,
        "PNG",
        0,
        0,
        pdfWidth,
        imgHeight
      );
      heightLeft -= pdfHeight;
    }

    pdf.save(`${filePrefix}.pdf`);
  };

  return { exportPDF };
}
