import { useEffect, useState } from "react";
import api from "@/utils/api";
import html2canvas from "html2canvas";
import jsPDF from "jspdf";
import Papa from "papaparse";

import ActualitesList from "@/components/admin/ActualitesList";
import ActualiteCreateModal from "@/components/admin/ActualiteCreateModal";
import ActualiteEditModal from "@/components/admin/ActualiteEditModal";

export default function AdminActualites() {
  const [actualites, setActualites] = useState([]);
  const [mois, setMois] = useState("");
  const [annee, setAnnee] = useState("");
  const [categorie, setCategorie] = useState("");

  const [openCreate, setOpenCreate] = useState(false);
  const [editing, setEditing] = useState(null);

  const fetchData = async () => {
    try {
      // Si ton backend ne filtre pas encore /actualites, tu peux appliquer un filtre côté client
      const params = {};
      if (mois) params.mois = mois;        // ignoré côté backend pour l’instant
      if (annee) params.annee = annee;     // idem
      if (categorie) params.categorie = categorie;

      const { data } = await api.get("/actualites", { params });
      setActualites(data || []);
    } catch (error) {
      console.error("Erreur chargement actualités :", error);
    }
  };

  useEffect(() => {
    fetchData();
  }, [mois, annee, categorie]);

  const exportPDF = async () => {
    const element = document.getElementById("actualites-section");
    const canvas = await html2canvas(element);
    const imgData = canvas.toDataURL("image/png");
    const pdf = new jsPDF();
    pdf.addImage(imgData, "PNG", 10, 10, 190, 0);
    pdf.save("actualites.pdf");
  };

  const exportCSV = () => {
    const data = actualites.map((actu) => ({
      Titre: actu.titre,
      Date: String(actu.date_publication || "").substring(0,10),
      Catégorie: actu.categorie || "",
      Résumé:
        actu.resume ||
        (actu.contenu || "").replace(/<[^>]+>/g, "").slice(0, 200),
    }));
    const csv = Papa.unparse(data);
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = "actualites.csv";
    a.click();
    URL.revokeObjectURL(url);
  };

  // Callbacks modals
  const handleCreated = (created) => {
    // on ajoute en tête
    setActualites((prev) => [created, ...prev]);
  };

  const handleUpdated = (updated) => {
    setActualites((prev) => prev.map((a) => (a.id === updated.id ? updated : a)));
  };

  const handleDelete = async (item) => {
    if (!confirm(`Supprimer "${item.titre}" ?`)) return;
    try {
      await api.delete(`/actualites/${item.id}`);
      setActualites((prev) => prev.filter((a) => a.id !== item.id));
    } catch (e) {
      console.error("Suppression impossible :", e);
      alert(e?.response?.data?.message || "Suppression impossible.");
    }
  };

  return (
    <div className="p-6">
      <h1 className="text-2xl font-bold text-red-600 mb-4">Gestion des Actualités</h1>

      {/* Filtres */}
      <div className="flex flex-wrap gap-4 mb-4">
        <select onChange={(e)=>setMois(e.target.value)} value={mois} className="border p-2 rounded">
          <option value="">Tous les mois</option>
          {[...Array(12)].map((_, i) => (
            <option key={i+1} value={i+1}>Mois {i+1}</option>
          ))}
        </select>

        <select onChange={(e)=>setAnnee(e.target.value)} value={annee} className="border p-2 rounded">
          <option value="">Toutes les années</option>
          {[2023, 2024, 2025, 2026].map((y) => (
            <option key={y} value={y}>{y}</option>
          ))}
        </select>

        <select onChange={(e)=>setCategorie(e.target.value)} value={categorie} className="border p-2 rounded">
          <option value="">Toutes les catégories</option>
          <option value="Formation">Formation</option>
          <option value="Annonce">Annonce</option>
          <option value="Événement">Événement</option>
          <option value="Projet">Projet</option>
          <option value="Autre">Autre</option>
        </select>
      </div>

      {/* Boutons Export */}
      <div className="flex gap-4 mb-4">
        <button onClick={exportPDF} className="bg-red-600 text-white px-4 py-2 rounded hover:bg-red-700">
          Export PDF
        </button>
        <button onClick={exportCSV} className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700">
          Export CSV
        </button>
      </div>

      {/* Liste + actions */}
      <div id="actualites-section">
        <ActualitesList
          items={actualites}
          onCreate={() => setOpenCreate(true)}
          onEdit={(a) => setEditing(a)}
          onDelete={handleDelete}
        />
      </div>

      {/* Modals */}
      <ActualiteCreateModal
        open={openCreate}
        onClose={() => setOpenCreate(false)}
        onSaved={handleCreated}
      />
      <ActualiteEditModal
        open={!!editing}
        actualite={editing}
        onClose={() => setEditing(null)}
        onSaved={handleUpdated}
      />
    </div>
  );
}
