// 📁 src/pages/admin/DashboardHome.jsx
import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import StatResumePage from "./StatResumePage";
import ActualiteStatsCard from "@/components/admin/ActualiteStatsCard";
import { Loader2, Briefcase, FileText, UserPlus } from "lucide-react";
import StatCard from "@/components/admin/StatCard";
import api from "@/utils/api";
import toast from "react-hot-toast";

export default function DashboardHome() {
  const navigate = useNavigate();

  // Filtres globaux
  const [year, setYear] = useState(new Date().getFullYear());
  const [month, setMonth] = useState("");

  // Stats “cartes” (endpoint /admin/stats)
  const [topStats, setTopStats] = useState(null);
  const [loadingTop, setLoadingTop] = useState(true);

  // Résumé détaillé (endpoint /admin/stats/resume)
  const [statsResume, setStatsResume] = useState(null);
  const [loadingResume, setLoadingResume] = useState(true);

  // --- Fetch cartes haut de page ---
  useEffect(() => {
    const token = localStorage.getItem("adminToken") || sessionStorage.getItem("adminToken");
    if (!token) {
      setLoadingTop(false);
      setLoadingResume(false);
      return;
    }
    const ac = new AbortController();

    (async () => {
      try {
        setLoadingTop(true);
        const { data } = await api.get("/admin/stats", {
          params: { year, month: month || undefined },
          signal: ac.signal,
        });
        setTopStats(data || {});
      } catch (e) {
        if (ac.signal.aborted) return;
        const status = e?.response?.status;
        const msg = e?.response?.data?.message || e?.message || "Erreur stats";
        console.error("Erreur /admin/stats :", e);
        toast.error(`Stats: ${status ?? ""} ${msg}`);
        if (status === 401 || status === 403) {
          localStorage.removeItem("adminToken");
          sessionStorage.removeItem("adminToken");
          navigate("/admin/login", { replace: true });
        }
      } finally {
        if (!ac.signal.aborted) setLoadingTop(false);
      }
    })();

    return () => ac.abort();
  }, [year, month, navigate]);

  // --- Fetch résumé détaillé ---
  useEffect(() => {
    const token = localStorage.getItem("adminToken") || sessionStorage.getItem("adminToken");
    if (!token) {
      setLoadingResume(false);
      return;
    }
    const ac = new AbortController();

    (async () => {
      try {
        setLoadingResume(true);
        const { data } = await api.get("/admin/stats/resume", {
          params: { year, month: month || undefined },
          signal: ac.signal,
        });
        setStatsResume(data || null);
      } catch (e) {
        if (ac.signal.aborted) return;
        const status = e?.response?.status;
        const msg = e?.response?.data?.message || e?.message || "Erreur";
        console.error("Erreur /admin/stats/resume :", e);
        toast.error(`Stats résumé: ${status ?? ""} ${msg}`);
        if (status === 401 || status === 403) {
          localStorage.removeItem("adminToken");
          sessionStorage.removeItem("adminToken");
          navigate("/admin/login", { replace: true });
        }
        setStatsResume(null);
      } finally {
        if (!ac.signal.aborted) setLoadingResume(false);
      }
    })();

    return () => ac.abort();
  }, [year, month, navigate]);

  return (
    <div className="p-4 space-y-6">
      <h1 className="text-2xl font-bold text-gray-800">Tableau de bord</h1>

      {/* Filtres */}
      <div className="flex flex-wrap gap-2 items-center">
        <label className="text-sm text-muted-foreground">Filtrer par mois :</label>
        <select
          value={month}
          onChange={(e) => setMonth(e.target.value)}
          className="border rounded px-2 py-1 text-sm"
        >
          <option value="">Tous les mois</option>
          {["01","02","03","04","05","06","07","08","09","10","11","12"].map((m) => (
            <option key={m} value={m}>{m}</option>
          ))}
        </select>
      </div>

      {/* Cartes de résumé (top) */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4" id="dashboard">
        {loadingTop ? (
          <div className="col-span-4 flex justify-center items-center py-10">
            <Loader2 className="animate-spin h-6 w-6 text-gray-500" />
            <span className="ml-2">Chargement des statistiques...</span>
          </div>
        ) : (
          <>
            <StatCard title="Offres"        icon={<Briefcase className="text-blue-500" />}  value={topStats?.total_offres ?? 0} />
            <StatCard title="Candidatures"  icon={<FileText  className="text-green-500" />} value={topStats?.total_candidatures ?? 0} />
            <StatCard title="Utilisateurs"  icon={<UserPlus  className="text-yellow-500" />} value={topStats?.total_utilisateurs ?? 0} />
            <StatCard title="Actualités"    icon={<FileText  className="text-red-500" />}   value={topStats?.total_actualites ?? 0} />
          </>
        )}
      </div>

      {/* Statistiques détaillées (prop data) */}
      <StatResumePage
        embedMode
        yearDefault={year}
        onYearChange={setYear}
        month={month}
        data={statsResume}       // ✅ ICI on passe la data (corrige l'erreur)
      />

      {/* Statistiques des actualités (camembert / liste réduite) */}
      <ActualiteStatsCard reduced year={year} month={month} />
    </div>
  );
}
